<?php get_header(); ?><section class="ga-section"><div class="ga-container"><?php if(have_posts()):?><div class="ga-posts"><?php while(have_posts()):the_post();?><article class="ga-post-card"><p class="ga-meta"><?php echo esc_html(get_the_date()); ?></p><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><div class="ga-content"><?php the_excerpt(); ?></div><a href="<?php the_permalink(); ?>">Continuar lendo</a></article><?php endwhile;?></div><div class="ga-pagination"><?php the_posts_pagination(); ?></div><?php else:?><h1>Nenhum conteúdo encontrado</h1><?php endif;?></div></section><?php get_footer(); ?>